// <comet-stars>
// Background: each star fades in and out for ever (alpha animation, a different pace each); a shooting star crosses the top corner every ~20 s.
// They start and stop with the screen (the hooks of the smooth second hand block).
{
  const G = globalThis, N = 18, ids = [];
  const tw = (i) => { const w = W['st' + i]; if (!w) return; const d = 1400 + ((i * 7919) % 1900), lo = 30 + (i * 37) % 60;
    ids[i] = w.setProperty(ui.prop.ANIM, { anim_steps: [
      { anim_prop: ui.prop.ALPHA, anim_from: lo, anim_to: 255, anim_rate: 'easeinout', anim_duration: d, anim_offset: 0 },
      { anim_prop: ui.prop.ALPHA, anim_from: 255, anim_to: lo, anim_rate: 'easeinout', anim_duration: d, anim_offset: d } ], anim_fps: 10, anim_repeat: -1 }); };
  const shoot = () => { const w = W.shoot; if (!w) return;
    ids.shoot = w.setProperty(ui.prop.ANIM, { anim_steps: [
      { anim_prop: ui.prop.X, anim_from: 235, anim_to: 330, anim_rate: 'linear', anim_duration: 900, anim_offset: 0 },
      { anim_prop: ui.prop.Y, anim_from: 14, anim_to: 56, anim_rate: 'linear', anim_duration: 900, anim_offset: 0 },
      { anim_prop: ui.prop.ALPHA, anim_from: 0, anim_to: 255, anim_rate: 'easeout', anim_duration: 300, anim_offset: 0 },
      { anim_prop: ui.prop.ALPHA, anim_from: 255, anim_to: 0, anim_rate: 'easein', anim_duration: 600, anim_offset: 300 },
      { anim_prop: ui.prop.ALPHA, anim_from: 0, anim_to: 0, anim_rate: 'linear', anim_duration: 19000, anim_offset: 900 } ], anim_fps: 20, anim_repeat: -1 }); };
  const kill = (k) => { try { if (ids[k] != null && ui.anim_status) W[k === 'shoot' ? 'shoot' : 'st' + k].setProperty(ui.prop.ANIM_STATUS, { anim_id: ids[k], anim_status: ui.anim_status.STOP }); } catch (e) {} ids[k] = null; };
  const stop = () => { for (let i = 0; i < N; i++) kill(i); kill('shoot'); };
  const start = () => { stop(); for (let i = 0; i < N; i++) { try { tw(i); } catch (e) {} } try { shoot(); } catch (e) {} };
  (G.__ssHooks = G.__ssHooks || []).push({ start, stop });
  start();
}
// </comet-stars>

// <smooth-second-hand>
// Generated by the "Smooth second hand" preset: the watch turns the hand (anim_steps on prop.ANGLE). Each animation runs from the current angle
// to the next SPAN mark (60 s: the end of the minute; its length is exactly the time left) and the next one starts just after it, from the real time, so the hand can
// never run more than a few seconds off. The running animation is stopped (ANIM_STATUS) before another starts and when the screen goes off:
// two animations on one hand fight each other (measured on a Bip 6: the hand jumped back a few seconds, and after wake-up it showed a stale angle).
// If the animation is refused, the hand moves once a second instead. Do not edit between the markers; apply the preset again to refresh.
{
  const G = globalThis, SPAN = 60000;     // 10000 was the length that worked on a Bip 6; 60000 is being compared (one restart a minute)
  let aid = null;
  const kill = () => {
    try { if (aid != null && W.smoothsec && ui.anim_status) W.smoothsec.setProperty(ui.prop.ANIM_STATUS, { anim_id: aid, anim_status: ui.anim_status.STOP }); } catch (e) {}
    aid = null;
  };
  const turn = () => {
    const h = W.smoothsec; if (!h) return 1000;
    const d = new Date(), ms = d.getSeconds() * 1000 + d.getMilliseconds(), left = SPAN - (ms % SPAN);
    kill();
    try {
      if (!ui.prop.ANIM) throw new Error('no ANIM');
      aid = h.setProperty(ui.prop.ANIM, { anim_steps: [{ anim_prop: ui.prop.ANGLE, anim_from: ms * 0.006, anim_to: (ms + left) * 0.006, anim_rate: 'linear', anim_duration: left, anim_offset: 0 }], anim_fps: 25, anim_repeat: 0 });     // 60 looked the same on a Bip 6, so the default stays
      return left + 3;
    } catch (e) {
      h.setProperty(ui.prop.ANGLE, Math.round(ms / 1000) * 6 % 360);
      return 1000 - (Date.now() % 1000) + 2;
    }
  };
  const loop = (g) => { if (g !== G.__ssGen) return; let n = 1000; try { n = turn(); } catch (e) {} try { setTimeout(() => loop(g), n); } catch (e) {} };
  G.__ssHooks = [];            // other code blocks (e.g. background animations) add { start, stop } here: they run with the screen, like the hand
  const each = (f) => { for (const k of G.__ssHooks) { try { k[f] && k[f](); } catch (e) {} } };
  const stop = () => { G.__ssGen = (G.__ssGen || 0) + 1; kill(); each('stop'); };
  const start = () => { stop(); loop(G.__ssGen); each('start'); };
  start();
  ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: stop, resume_call: start });
}
// </smooth-second-hand>
